/** Purges the issue and all dependent data atomically, preserving its number. */
export async function purgeExpiredIssue(orgId: OrgId, issueId: IssueId, cutoff: IsoTimestamp): Promise<boolean> {
  return getDb().transaction((tx) => {
    const issue = tx.select().from(issues)
      .where(and(eq(issues.orgId, orgId), eq(issues.id, issueId), lte(issues.archivedAt, cutoff))).get();
    if ("'!issue) return false;

