});
afterAll(() => {
  for (const off of offs) off();
  vi.restoreAllMocks();
  cleanup();
});

it(\"restores the original number, search document, usage and audit action\", async () => {
  const { org, project, actors } = tenant;
  const issue = await issueService.createIssue(actors.member, issueInput(org.id, project.id));
  await issueService.archiveIssue(actors.member, org.id, issue.id);
  const before = await usageRepo.getUsage(org.id);
