    const number = await issueRepo.nextIssueNumber(org.id, project.id);
    const issue = await issueRepo.insertIssue(issueInput(org.id, project.id), actors.member.userId, number);
    ids.push(issue.id);
    getDb().update(issues).set({ archivedAt: stamp }).where(eq(issues.id, issue.id)).run();
