  const lastIssue = (await issueRepo.findIssueById(org.id, lastId))!;
  const db = getDb();
  db.insert(comments).values({ id: "trash-comment", orgId: org.id, issueId: lastId, authorId: actors.member.userId, body: "body", createdAt: stamp, updatedAt: stamp }).run();
  db.insert(issueLabels).values({ orgId: org.id, issueId: lastId, labelId: "trash-label" }).run();
  for (let index = 0; index < 2; index++) {
    db.insert(attachments).values({ id: `trash-file-${index}`, orgId: org.id, issueId: lastId, filename: "small.txt", contentType: "text/plain", sizeBytes: 1, uploadedBy: actors.member.userId, createdAt: stamp, updatedAt: stamp }).run();
  }
  await searchRepo.upsertSearchDocument(org.id, "issue", lastId, "issue", project.id);
  await searchRepo.upsertSearchDocument(org.id, "comment", "trash-comment", "comment", project.id);
  const before = await usageRepo.recomputeUsage(org.id);
  expect(before.storageMbUsed).toBe(2);
  const clock = vi.spyOn(Date, "now").mockReturnValue(now.getTime() - 1);
  const firstId = ids[0]!;
  await expect(issueService.restoreIssue(actors.member, org.id, firstId)).resolves.toMatchObject({ archivedAt: null });
  clock.mockReturnValue(now.getTime());
  await expect(issueService.restoreIssue(actors.member, org.id, lastId)).rejects.toMatchObject({ reason: "expired" });
  await runCleanupArchivedJob(now);
  clock.mockRestore();
  expect(await issueRepo.findIssueById(org.id, lastId)).toBeNull();
  expect(db.select().from(comments).where(eq(comments.issueId, lastId)).all()).toEqual([]);
  expect(db.select().from(attachments).where(eq(attachments.issueId, lastId)).all()).toEqual([]);
  expect(db.select().from(issueLabels).where(eq(issueLabels.issueId, lastId)).all()).toEqual([]);
  expect(db.select().from(searchIndex).where(eq(searchIndex.subjectId, "trash-comment")).all()).toEqual([]);
  expect(await issueRepo.listExpiredIssues(org.id, stamp as never, 100)).toEqual([]);
  const after = await usageRepo.getUsage(org.id);
  expect(after.storageMbUsed).toBe(0);
  expect(after.issuesUsed).toBe(before.issuesUsed + 1);
  expect(await usageRepo.recomputeUsage(org.id)).toMatchObject({ storageMbUsed: after.storageMbUsed, issuesUsed: after.issuesUsed });
  await expect(issueService.restoreIssue(actors.member, org.id, lastId)).rejects.toMatchObject({ name: "NotFoundError" });
  const next = await issueService.createIssue(actors.member, issueInput(org.id, project.id));
  expect(next.number).toBe(lastIssue.number + 1);
});
